import {
  DeleteObjectCommand,
  GetObjectCommand,
  NoSuchKey,
  PutObjectCommand,
  S3Client,
} from '@aws-sdk/client-s3';
import { mkdir, readFile, unlink, writeFile } from 'node:fs/promises';
import path from 'node:path';

/** Where attachment bytes live. Keys are generated by the server (`<requestId>/<uuid>`), never by a client. */
export interface FileStorage {
  put(key: string, data: Buffer): Promise<void>;
  /** Null if there is nothing under that key. */
  get(key: string): Promise<Buffer | null>;
  /** Missing files are fine — deleting twice is not an error. */
  remove(key: string): Promise<void>;
}

const KEY = /^[0-9a-f-]{36}\/[0-9a-f-]{36}$/;
const assertKey = (key: string) => {
  if (!KEY.test(key)) throw new Error('Invalid storage key.');
};

/** Plain files under one directory (default `./uploads`, or UPLOAD_DIR). No path from a client ever reaches the disk. */
export class LocalFileStorage implements FileStorage {
  constructor(private readonly root: string) {}

  private pathFor(key: string) {
    assertKey(key);
    return path.join(this.root, key);
  }

  async put(key: string, data: Buffer) {
    const file = this.pathFor(key);
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, data, { flag: 'wx' });
  }

  async get(key: string) {
    try {
      return await readFile(this.pathFor(key));
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw err;
    }
  }

  async remove(key: string) {
    try {
      await unlink(this.pathFor(key));
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== 'ENOENT') throw err;
    }
  }
}

/**
 * Objects in one S3 bucket, under `<prefix><key>`. Credentials come from the default
 * AWS provider chain (the EC2 instance role in production) — never from config.
 */
export class S3FileStorage implements FileStorage {
  private readonly client: S3Client;

  constructor(
    region: string,
    private readonly bucket: string,
    private readonly prefix: string,
  ) {
    this.client = new S3Client({ region });
  }

  private objectKey(key: string) {
    assertKey(key);
    return `${this.prefix}${key}`;
  }

  async put(key: string, data: Buffer) {
    await this.client.send(
      new PutObjectCommand({
        Bucket: this.bucket,
        Key: this.objectKey(key),
        Body: data,
        // Never overwrite, like the local `wx` flag.
        IfNoneMatch: '*',
      }),
    );
  }

  async get(key: string) {
    try {
      const res = await this.client.send(
        new GetObjectCommand({ Bucket: this.bucket, Key: this.objectKey(key) }),
      );
      if (!res.Body) return null;
      return Buffer.from(await res.Body.transformToByteArray());
    } catch (err) {
      if (err instanceof NoSuchKey) return null;
      throw err;
    }
  }

  async remove(key: string) {
    await this.client.send(
      new DeleteObjectCommand({ Bucket: this.bucket, Key: this.objectKey(key) }),
    );
  }
}
